import{_ as p,c as d,a as r,o as e}from"./app-BKm_FHq2.js";const a={};function h(o,t){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="软件工程复习资料" tabindex="-1"><a class="header-anchor" href="#软件工程复习资料"><span>软件工程复习资料</span></a></h1><div style="background:#f8f9fa;padding:12px 16px;border-left:3px solid #4CAF50;margin-bottom:16px;border-radius:0 4px 4px 0;font-size:0.9rem;"><div style="display:flex;align-items:center;gap:30px;flex-wrap:wrap;"><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">📅</span><span>记不清了</span></div><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">✍️</span><span>Jixer</span></div></div></div><p>有人将软件的发展过程划分为4个阶段：</p><p>第一阶段（20世纪50年代）称为“程序设计的原始时期”。这时既没有（A.汇编语言），也没有（B.高级语言），程序员只能用机器指令编写程序。</p><p>第二阶段（20世纪60年代）称为“基本软件期”。出现了（A.汇编语言），并逐渐普及。随着（B.高级语言）的发展，编译技术也有较大的发展。</p><p>第三阶段（20世纪60年代末-70年代中）称为“程序设计方法时代”。这一时期，与硬件价格下降相反，软件开发费用急剧上升。人们提出了（C.结构化程序设计）和（D.模块化程序设计）等程序设计方法，设法降低软件的开发费用。</p><p>第四阶段（20世纪70年代中期至今）称为“软件工程时期”，软件开发技术不再仅仅是程序设计技术，而是包括了与软件开发的各个阶段，如（E.需求定义）、（F.设计）、编码、单元测试、综合测试、（G.使用和维护）及其整体有关的各种管理技术。</p><hr><p>例如：修改一个已有的库存清单系统，使它能在每天送给采购员一份定货报表。修改已有的库存清单并且编写产生报表的程序，估计共需5000元；系统修改后，能及时定货将消除零件短缺影响生产的问题，估计因此每年可以节省2500元。五年共可以节省12500元。但不能简单地把现在的5000元与五年后的12500元相比。</p><p>假设年利率为12%，可以算出修改库存清单系统后每年预计节省的钱的现在价值。</p><p>表2-1 将来的收入折算成现在的价值</p><p>年 将来值（元） (1+i)n 现在值（元） 累计的现在值（元）</p><p>1 2500 1.12 2232.14 2232.14</p><p>2 2500 1.2544 1992.98 4225.12</p><p>3 2500 1.40493 1779.45 6004.57</p><p>4 2500 1.57352 1588.80 7593.37</p><p>5 2500 1.76234 1418.57 9011.94</p><hr><p>判断正误：可行性研究报告应评述为了合理地达到开发目标而可能选择的各种方案，以便用户进行抉择。因此，编写者不必提出结论。</p><p>答案：错</p><hr><p>例题，请用判定表表示下面描述的耗电记费系统中电费的计算方法</p><p>耗电记费系统可以采用固定价格收费和浮动价格收费两种方式。若采用固定价格方式收费，对每月耗电100KW•h以下的用户只征收最低标准费，超过100KW•h的用户按价格表A收费；若采用浮动价格方式收费，则每月耗电100KW•h以下的用户按价格表A收费，超过100KW•h的用户按价格表B收费。</p><p>答案：</p><p>条</p><p>件 收费方式 固定 固定 浮动 浮动</p><pre><code>耗电规模    &gt;100    ≤100   &gt;100    ≤100
</code></pre><p>操</p><p>作 征收最低标准费 √</p><pre><code>按价格表A收费  √         √

按价格表B收费         √  
</code></pre><p>条</p><p>件 固定 固定 浮动 浮动</p><pre><code>\\&gt;100    ≤100   &gt;100    ≤100
</code></pre><p>操作 按价格表A收费 征收最低标准费 按价格表B收费 按价格表A收费</p><hr><p>软件需求分析的任务不应包括（A.结构化程序设计）。进行需求分析可使用多种工具，但（B.PAD图）是不适用的。在需求分析中，分析员要从用户那里解决的最重要的问题是（C.要让软件做那么）。需求规格说明书的内容不应当包括（D.对算法的详细过程性描述）。该文档在软件开发中具有重要的作用，但其作用不应当包括（E.软件可行性分析的依据）。</p><hr><p>在结构化分析方法中，用以表达系统内数据的运动情况的工具有（A.数据流图）</p><hr><p>在众多的设计方法中，SD方法是最受人注意的，也是最广泛应用的一种，这种方法可以同分析阶段的（A.SA）方法及编程阶段的（B.SP）方法前后衔接，SD方法考虑如何建立一个结构良好的程序结构，它提出了评价模块结构质量的两个具体标准-块间联系和块内联系。SD方法的最终目标是（C.块间联系小，块内联系大），用于表示模块间调用关系的图叫（D.SC）。</p><p>另一种比较著名的设计方法是以信息隐蔽为原则划分模块，这种方法叫（E.Parnas）方法。</p><hr><p>块间联系和块内联系是评价程序模块结构质量的重要标准。联系的方式、共用信息的作用、共用信息的数量和接口的（A.简单性）等因素决定了块间联系的大小。在块内联系中，（B.功能内聚）的块内联系最强。</p><p>SD方法的总的原则是使每个模块执行（C.一个）功能，模块间传送（D.数据型）参数，模块通过（E.标准调用）语句调用其它模块，而且模块间传送的参数应尽量（F.少）。</p><p>此外，SD方法还提出了判定的作用范围和模块的控制范围等概念。SD方法认为，（G.作用范围）应该是（H.控制范围）的子集。</p><hr><p>10.从下列有关系统结构图的叙述中选出正确的叙述</p><p>1） 系统结构图中反映的是程序中数据流的情况。</p><p>2） 系统结构图是精确表达程序结构的图形表示法。因此，有时可将系统结构图当作程序流程图使用。</p><p>3） 一个模块的多个下属模块在系统结构图中所处的左右位置是无关紧要的。</p><p>4） 在系统结构图中，上级模块与其下属模块之间的调用关系用有向线段表示。这时，使用斜的线段和水平、垂直的线段具有相同的含义。</p><p>答案：4</p><hr><p>[99年统考]在完成软件概要设计，并编写出相关文档之后，应当组织对概要设计工作的评审。评审的内容包括：</p><p>分析该软件的系统结构、子系统结构，确认该软件设计是否覆盖了所有已确定的软件需求，软件每一成分是否可（A.追溯）到某一项需求。</p><p>分析软件各部分之间的联系，确认该软件的内部接口与外部接口是否已经明确定义。模块是否满足（B.高内聚）和（C.低耦合）的要求。模块（D.作用范围）是否在其（E.控制范围）之内。</p><hr><p>[2001年统考]在典型的软件体系结构中应包括5种构件，它们是（A）、（B）、（C）、（D）、（E）。</p><p>其中，（A.纯计算构件）具有简单的输入/输出关系，没有运行状态的变化。例如，数值计算、过滤器、转换器等。（B.存储构件）用于存放共享的、永久性的、结构化的数据。例如，数据库、文件、符号表、超文本等。（C.管理构件）使得执行的操作与运行状态紧密耦合。例如，抽象数据类型、面向对象系统中的对象、许多服务器等。（D.控制构件）管理其它构件运行的时间、时机及次序。例如，调度器、同步器等。（E.链接构件）在实体之间传递信息。例如，通信机制、用户界面等。</p><hr><p>软件详细设计工具可分为3类，即图形工具、设计语言和表格工具。图形工具中，（A.流程图）简单而应用广泛。（B.NS图）表示法中，每个处理过程用一个盒子表示，盒子可以嵌套。（C.PAD图）可以纵横延伸，图形的空间效果好。</p><p>（D.PDL）是一种设计和描述程序的语言，它是一种面向（E.人）的语言。</p><hr><p>[2001年统考]下面是两个程序流程图，试分别用N-S图和PAD图表示之，并计算它们的McCabe复杂性度量。</p><p><a href="https://imgse.com/i/piH7ho6" target="_blank" rel="noopener noreferrer"><img src="https://s11.ax1x.com/2023/12/25/piH7ho6.png" alt="piH7ho6.png"></a></p><p>答案：</p><p><a href="https://imgse.com/i/piH75FK" target="_blank" rel="noopener noreferrer"><img src="https://s11.ax1x.com/2023/12/25/piH75FK.png" alt="piH75FK.png"></a></p><p>PAD图略</p><p>McCabe复杂性度量都为3。（7-6+2）</p><hr><p>下图是使用BASIC语言编写的一个打印A、B、C三数中最小者的程序流程图。其中出现了6个GOTO语句，1个向前，5个向后，程序可读性很差。</p><p><a href="https://imgse.com/i/piH7oWD" target="_blank" rel="noopener noreferrer"><img src="https://s11.ax1x.com/2023/12/25/piH7oWD.png" alt="piH7oWD.png"></a></p><p>if (A&lt;B) goto 120;</p><p>if (B&lt;C) goto 110;</p><p>100 print C;</p><p>goto 140;</p><p>110 print B;</p><p>goto 140;</p><p>120 if (A&lt;C) goto 130;</p><p>goto 100;</p><p>130 print A;</p><p>140</p><p>试利用基本控制结构，将程序中的GOTO语句消去。</p><p>使用if-then-else结构化构造，则上述程序段可改成如下形式：</p><p>if (A&lt;B and A&lt;C) then</p><pre><code>  print A
</code></pre><p>else if (A&gt;=B and B&lt;c) then</p><pre><code>  print B
</code></pre><p>else</p><p>print C</p><hr><p>从下列叙述中选出5条符合程序设计风格指导原则的叙述。</p><p>①嵌套的重数应加以限制</p><p>②尽量多使用临时变量</p><p>③不滥用语言特色</p><p>④不用可以省略的括号</p><p>⑤使用有意义的变量名</p><p>⑥应尽可能把程序编得短些</p><p>⑦把常见的局部优化工作留给编译程序去做</p><p>⑧注解越少越好</p><p>⑨程序的格式应有助于读者理解程序</p><p>⑩应尽可能多用GOTO语句</p><p>答案：①、③、⑤、⑦、⑨是正确的</p><hr><p>从下列关于模块化程序设计的叙述中选出5条正确的叙述。</p><p>①程序设计比较方便，但比较难以维护</p><p>②便于由多个人分工编制大型程序</p><p>③软件的功能便于扩充</p><p>④程序易于理解，也便于排错</p><p>⑤在主存储器能够容纳得下的前提下，应使模块尽可能大，以便减少模块的个数</p><p>⑥模块之间的接口叫做数据文件</p><p>⑦只要模块之间的接口关系不变，各模块内部实现细节的修改将不会影响别的模块</p><p>⑧模块间的单向调用关系叫做模块的层次结构</p><p>⑨模块越小，模块化的优点越明显。一般来说，模块的大小都在10行以下</p><p>答案：②、③、④、⑦、⑧是正确的</p><hr><p>[2000年统考]设要对一个自动饮料售货机软件进行黑盒测试。该软件的规格说明如下：</p><p>有一个处理单价为1元5角钱的盒装饮料的自动售货机软件。若投入1元5角硬币，按下“橙汁”、“啤酒”或“红茶”按钮，相应的饮料就送出来。若投入的是2元硬币，在送出饮料的同时退还5角硬币。</p><p>1）（5分）试利用因果图法，建立该软件的因果图；</p><p>2）（5分）设计测试该软件的全部测试用例。</p><p><a href="https://imgse.com/i/piH7byd" target="_blank" rel="noopener noreferrer"><img src="https://s11.ax1x.com/2023/12/25/piH7byd.png" alt="piH7byd.png"></a></p><p>因果图（加入了两个中间结点11和12。11表示已投币，12表示已按钮）</p><p>测试用例</p><table><thead><tr><th></th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th><th>6</th><th>7</th><th>8</th><th>9</th><th>10</th><th>11</th><th></th><th></th></tr></thead><tbody><tr><td>输入</td><td>投入1元5角硬币</td><td>(1)</td><td>1</td><td>1</td><td>1</td><td>1</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td></tr><tr><td>投入2元硬币</td><td>(2)</td><td>0</td><td>0</td><td>0</td><td>0</td><td>1</td><td>1</td><td>1</td><td>1</td><td>0</td><td>0</td><td>0</td><td></td></tr><tr><td>按”橙汁”按钮</td><td>(3)</td><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td></td></tr><tr><td>按”啤酒”按钮</td><td>(4)</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td>0</td><td></td></tr><tr><td>按”红茶”按钮</td><td>(5)</td><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td></td></tr><tr><td>中间结点</td><td>已投币</td><td>(11)</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>0</td><td>0</td><td>0</td></tr><tr><td>已按钮</td><td>(12)</td><td>1</td><td>1</td><td>1</td><td>0</td><td>1</td><td>1</td><td>1</td><td>0</td><td>1</td><td>1</td><td>1</td><td></td></tr><tr><td>输出</td><td>退还5角硬币</td><td>(21)</td><td>0</td><td>0</td><td>0</td><td>0</td><td>1</td><td>1</td><td>1</td><td>0</td><td>0</td><td>0</td><td>0</td></tr><tr><td>送出橙汁饮料</td><td>(22)</td><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td></td></tr><tr><td>送出啤酒饮料</td><td>(23)</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td></td></tr><tr><td>送出红茶饮料</td><td>(24)</td><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td><td>0</td><td></td></tr></tbody></table><hr><p>软件测试是软件质量保证的主要手段之一，测试的费用已超过（A.软件开发费用）的30%以上。因此，提高测试的有效性十分重要。“高产”的测试是指（B.用少量的测试用例运行程序，发现被测程序尽可能多的错误）。根据国家标准GB8566-88《计算机软件开发规范》的规定，软件的开发和维护划分为8个阶段，其中，单元测试是在（C.实现）阶段完成的，集成测试的计划是在（D.概要设计）阶段制定的，确认测试的计划是在（E.需求分析）阶段制定的。</p><hr><p>集成测试也叫做（A.组装测试）或（B.联合测试）。通常，在（C.单元测试）的基础上，将所有模块按照设计要求组装成系统。子系统的集成测试特别称为（D.部件测试），它所作的工作是要找出子系统和系统需求规格说明之间的（E.不一致）。需要考虑的问题是在把各个模块连接起来的时候，穿越模块接口的数据是否会（F.丢失）；一个模块的功能是否会对另一个模块的功能产生不利的影响；各个（G.子功能）组合起来，能否达到预期要求的（H.父功能）；（I.全局数据结构）是否有问题；单个模块的误差累积起来是否会放大。</p><hr><p>软件测试方法可分为黑盒测试和白盒测试两种。</p><p>黑盒测试法是通过分析程序的（A.功能）来设计测试用例的方法。除了测试程序外，它还适用于对（B.需求分析）阶段的软件文档进行测试。</p><p>白盒测试法是根据程序的（C.内部逻辑）来设计测试用例的方法。除了测试程序外，它也适用于对（D.软件详细设计）阶段的软件文档进行测试。</p><p>白盒法测试程序时常按照给定的覆盖条件选取测试用例。（E.判定）覆盖比（F.语句）严格，它使得每个判定的每条分支至少经历一次。（G.判定/条件）覆盖既是判定覆盖，又是条件覆盖，但它并不保证使各种条件都能取到所有可能的值。（H.多重条件）覆盖比其他条件都要严格，但它不能保证覆盖程序中的每一条路径。</p><p>单元测试一般以（I.白盒法）为主，测试的依据是（J.模块功能规格说明）。</p><hr><p>从下列关于程序设计风格和软件测试的叙述中，选出5条正确的叙述</p><p>①用黑盒法测试时，测试用例是根据程序内部逻辑设计的。</p><p>②尽量用公共过程或子程序去代替重复的代码段。</p><p>③测试是为了验证该软件已正确地实现了用户的要求。</p><p>④对于连锁型分支结构，若有n个判定语句，则有2n条路径。</p><p>⑤尽量采用复合的条件测试，以避免嵌套的分支结构。</p><p>⑥GOTO语句概念简单，使用方便。在某些情况下，保留GOTO语句反能使写出的程序更加简洁。</p><p>⑦发现错误多的程序模块，残留在模块中的错误也多。</p><p>⑧黑盒测试方法中最有效的是因果图法。</p><p>⑨在做程序的单元测试时，桩（存根）模块比驱动模块容易编写。</p><p>⑩程序效率的提高主要应通过选择高效的算法来实现。</p><p>答案：④、⑤、⑥、⑦、⑩</p><hr><p>对一个长度为100,000条指令的程序进行测试，记录下来的数据如下：</p><p>.测试开始，发现错误个数为0；</p><p>.经过160小时的测试，累计改正100个错误，此时，MTTF=0.4小时；</p><p>.又经过160小时的测试，累计改正300个错误，此时，MTTF=2小时。</p><p>1） 估计程序中固有的错误总数。</p><p>2） 为使MTTF达到10小时，必须测试和调试这个程序多长时间？</p><p>3） 给出MTTF与测试时间t之间的函数关系</p><p>【23题放弃】</p><hr><p>定义一个人参加劳动时间的长短为（A.劳动量），其度量单位为PM（人月）或PY（人年）。而定义完成一个软件项目（或软件任务）所需的（A.劳动量）为（B.工作量），其度量单位是人月/项目（任务），记做PM（人月）。进一步地，定义单位（A.劳动量）所能完成的软件（C.产品）的数量为软件（D.生产率），其度量单位为LOC/PM。它表明一般指（E.开发全过程）的一个平均值。例如，一个软件的开发工作量如表所示，该软件共有源代码2900行，其中500行用于测试，2400行是执行（F.程序）的源代码。则劳动生产率是（G.240）（LOC/PM）。</p><p>软件开发所需工作量例</p><table><thead><tr><th>阶段 软件计划 需求分析 设计 编码 测试 总体</th></tr></thead><tbody><tr><td>需要工作量（人月） 1.0 1.5 3.0 1.0 3.5 10.0</td></tr></tbody></table><p>劳动生产率是（2900-500）/10=240（LOC/PM）</p><hr><p>[2000年统考]应用Coad和Yourdon方法构造和评审OOA概念模型时，应按如下的五个层次进行：</p><p>第一个层次是识别（A.类与对象）。它们是对应用中的概念的抽象，可以从用户要求书或其它规格说明中找到。</p><p>第二个层次是识别（B.属性）。它们是（A.类与对象）所保存的信息，同时要给出各个（A.类与对象）之间的实例连接。这些实例连接包括有1对1、1对多、多对多、多对1等联系。</p><p>第三个层次是识别（C.服务）。它们是（A.类与对象）可提供的操作，同时要根据需要的功能给出各个操作之间的消息连接。</p><p>第四个层次是建立（D.结构）。有两种（D.结构）：整体与部分；泛化与特化。前者表明一种聚合关系，后者表明一种继承关系。</p><p>第五个层次是识别（E.主题）。它相当于高层的模块或子系统。</p><hr><p>在面向对象软件开发过程中特别重视复用。软件构件应独立于当初开发它们的应用而存在。在以后的应用开发中，可以调整这些独立构件以适应新问题的需要。因此，应使得类成为一个（A.可复用）的单元。这样就有一个（B.类）生存期问题。（B.类）生存期有自己的步骤，与任何特定应用的开发（C.无关）。按照这些步骤，可以完整地描述一个基本（D.实体），而不仅仅考虑当前正在开发的系统。系统开发的各个阶段都可能会标识新的类。随着各个新类的标识，（B.类）生存期引导开发工作逐个阶段循序渐进。</p><p>在设计与实现类时，应尽可能利用既存类提供为当前应用所需要的功能，利用既存类的3个可能途径是：（E.照原样）复用既存类，对既存类进行（F.演化）以得到满足要求的类，重新开始进行开发。</p><hr><p>类常常被看作是一个抽象数据类型的实现，更合适的是把类看作是某种（A.概念）的一个模型。事实上，类是单个的（B.语义）单元。类的用户能够操纵的操作叫做类的（C.界面）。类定义的其余部分给出数据定义和辅助功能定义，包括类的实现。</p><p>类的实现常常包括了其它类的实例，这些实例（D.应受保护不）被其它对象存取，包括同一个类的其它实例。类的实现可能还包括某些私有方法，实现它们的类可以使用，而其它任何对象都不能使用。</p><p>类，就它是一个数据值的聚合的意义来看，与Pascal中的记录或C中的结构类似，但又有差别。类扩展了通常的记录语义，可提供各种级别的（E.可访问性）。类不同于记录，因为它们包括了操作的定义，这些操作与类中声明的数据值有相同的地位。</p><hr><p>简述软件工程的概念和基本原理。</p><p>答案：软件工程概念：软件工程是指导计算机软件开发和维护的一门工程学科。采用工程的概念、原理、技术和方法来开发与维护软件，把经过时间考验而证明正确的管理技术和当前能够得到的最好的技术方法结合起来，以经济地开发出高质量的软件并有效地维护它，这就是软件工程。</p><p>软件工程基本原理：</p><p>（1）用分阶段的生命周期计划严格管理；</p><p>（2）坚持进行阶段评审；</p><p>（3）实行严格的产品控制；</p><p>（4）采纳现代程序设计技术；</p><p>（5）结果应能清楚地审查；</p><p>（6）开发小组的人员应少而精；</p><p>（7） 承认不断改进软件工程实践的必要性</p><hr><p>简述数据流图的四种成分以及构造数据流图的步骤。</p><p>答案：</p><p>四种成分：数据源点/终点、加工处理、数据流和数据存储。</p><p>构造步骤：</p><p>（1）从问题描述中提取数据流图的上述四种成分</p><p>（2）构造系统的抽象模型，即画出顶层数据流图</p><p>（3）根据问题实际和分解原则，逐层分解高层数据流图中的处理，得到下一层次的数据流图子图。每一层次的分解对应上一层次的一个处理。</p><p>（4）重复第3步，进行逐层分解细化，直到所有处理为基本处理为止。</p><hr><p>简述常用的三种需求分析方法以及进行需求分析的原则。</p><p>答案：方法有结构化分析方法、面向对象的分析方法、原型化分析方法。</p><p>原则是：</p><p>（1）能够表达和理解问题的信息域和功能域。</p><p>（2）能够对问题进行分解和不断细化，建立问题的层次结构。</p><p>（3） 能够给出系统的逻辑表示和物理表示</p><hr><p>简述什么是模块独立性？实现模块独立性的优点是什么？衡量模块独立程度的两个定性标准是什么及其含义？</p><p>答案：</p><p>模块独立性是软件系统中每个模块只涉及软件要求的具体子功能，而和软件系统中其他的模块接口是简单的，符合信息隐藏和局部化原则，模块间关联和依赖程度尽可能小。</p><p>优点：</p><p>（1）有效的模块化的软件功能被划分，并且接口被简化，比较容易开发出来。</p><p>（2）由于因设计和编码修改引起的副作用受到局限，错误传播的可能性被减少，并且模块复用成为可能，所以独立的模块更易于维护和测试。</p><p>两个度量标准：</p><p>（1）耦合：衡量不同模块彼此间互相依赖（连接）的紧密程度。</p><p>内聚：衡量一个模块内部各个元素彼此结合的紧密程度。</p><hr><p>简述什么是静态分析测试？什么是动态执行测试？</p><p>答案：</p><p>静态分析技术：静态分析技术不执行被测试软件，可对需求分析说明书、软件设计说明书、源程序做结构检查、流图分析、符号执行等来找出软件错误。可以人工进行分析，也可以用测试工具静态分析程序来进行，被测试程序的正文作为输入，经静态分析程序分析得出分析结果。</p><p>动态分析技术：是执行被测程序，由执行结果分析程序可能出现的错误。可以人工设计程序测试用例，也可以由测试工具动态分析程序来做检查与分析。动态测试包括功能测试和结构测试。它把程序看作为一个函数，输入的全体称为函数的定义域，输出的全体称为函数的值域，函数则描述了输入的定义域与输出值域的关系。</p>`,217)])])}const i=p(a,[["render",h]]),s=JSON.parse('{"path":"/%E5%AD%A6%E6%A0%A1%E4%B9%A0%E9%A2%98/%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B%E5%A4%8D%E4%B9%A0%E8%B5%84%E6%96%99.html","title":"软件工程复习资料","lang":"en-US","frontmatter":{},"headers":[],"git":{"updatedTime":1772378218000,"contributors":[{"name":"lijunxi","username":"lijunxi","email":"2770063826@qq.com","commits":2,"url":"https://github.com/lijunxi"}],"changelog":[{"hash":"9f2e2eae9bf1528af2a053782edcdc5a1967682a","time":1772378218000,"email":"2770063826@qq.com","author":"lijunxi","message":"add vuepress"},{"hash":"c0e7c2d63343d3254f23fa31134bceb4e00c3331","time":1751790745000,"email":"2770063826@qq.com","author":"lijunxi","message":"add algorithm、school"}]},"filePathRelative":"学校习题/软件工程复习资料.md"}');export{i as comp,s as data};
